            if all(grid[rr][cc] == 3 for rr,cc in
                   ((r-1,c-1),(r-1,c),(r-1,c+1),(r,c-1),(r,c+1),(r+1,c-1),(r+1,c),(r+1,c+1))):
                centers.append((r,c))
    # For each frame, the 2-colored lattice travels in a single cardinal axis.
    for r,c in centers:
        vertical = sum(grid[rr][c] == 2 for rr in range(h))
        horizontal = sum(grid[r][cc] == 2 for cc in range(w))
        if vertical >= horizontal:
            for rr in range(h):
                if grid[rr][c] == 0:
                    out[rr][c] = 1
        else:
            for cc in range(w):
                if grid[r][cc] == 0:
                    out[r][cc] = 1
    return out
